import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

/**
 * Multi-tenant report generator CLI tool.
 * Generates HTML reports per tenant from structured log data.
 * Tenant isolation ensures each tenant only sees their own data.
 */
public class ReportGenerator {

    private static final Path BASE_DIR = Paths.get("/var/reports");
    private static final Pattern TENANT_ID_PATTERN = Pattern.compile("^[a-zA-Z0-9_-]{1,64}$");
    private static final Set<String> ALLOWED_THEMES = Set.of("light", "dark", "corporate");

    public static void main(String[] args) throws Exception {
        if (args.length < 3) {
            System.err.println("Usage: report-gen <tenant-id> <report-type> <theme>");
            System.exit(1);
        }
        String tenantId = args[0];
        String reportType = args[1];
        String theme = args[2];

        validateTenantId(tenantId);
        validateTheme(theme);

        TenantContext ctx = new TenantContext(tenantId, theme);
        List<LogEntry> entries = loadTenantLogs(ctx);
        String html = generateReport(ctx, reportType, entries);
        writeReport(ctx, reportType, html);
        System.out.println("Report generated for tenant: " + tenantId);
    }

    static void validateTenantId(String tenantId) {
        if (!TENANT_ID_PATTERN.matcher(tenantId).matches()) {
            throw new IllegalArgumentException("Invalid tenant ID");
        }
    }

    static void validateTheme(String theme) {
        if (!ALLOWED_THEMES.contains(theme)) {
            throw new IllegalArgumentException("Invalid theme: " + theme);
        }
    }

    static List<LogEntry> loadTenantLogs(TenantContext ctx) throws IOException {
        Path logFile = BASE_DIR.resolve(ctx.tenantId).resolve("events.log");
        if (!logFile.toRealPath().startsWith(BASE_DIR.toRealPath())) {
            throw new SecurityException("Path traversal detected");
        }
        List<LogEntry> entries = new ArrayList<>();
        if (Files.exists(logFile)) {
            for (String line : Files.readAllLines(logFile)) {
                entries.add(LogEntry.parse(line));
            }
        }
        return entries;
    }

    static String generateReport(TenantContext ctx, String reportType, List<LogEntry> entries) {
        StringBuilder sb = new StringBuilder();
        sb.append("<!DOCTYPE html>\n<html>\n<head>\n");
        sb.append("<meta charset=\"UTF-8\">\n");
        sb.append("<title>Report - ").append(encodeForHtmlContent(ctx.tenantId)).append("</title>\n");
        sb.append(buildStyleBlock(ctx.theme));
        sb.append("</head>\n<body>\n");
        sb.append("<div class=\"container\">\n");
        sb.append("<h1>").append(encodeForHtmlContent(reportType)).append(" Report</h1>\n");
        sb.append(buildSummarySection(ctx, entries));
        sb.append(buildDetailSection(ctx, entries));
        sb.append(buildNavigationScript(ctx, entries));
        sb.append("</div>\n</body>\n</html>");
        return sb.toString();
    }

    static String buildStyleBlock(String theme) {
        // Theme is validated against allowlist, safe to use
        return "<link rel=\"stylesheet\" href=\"/static/themes/" + theme + ".css\">\n";
    }

    static String buildSummarySection(TenantContext ctx, List<LogEntry> entries) {
        long errorCount = entries.stream().filter(e -> e.level.equals("ERROR")).count();
        long warnCount = entries.stream().filter(e -> e.level.equals("WARN")).count();
        return String.format("<div class=\"summary\"><p>Errors: %d</p><p>Warnings: %d</p></div>\n",
                errorCount, warnCount);
    }

    static String buildDetailSection(TenantContext ctx, List<LogEntry> entries) {
        StringBuilder sb = new StringBuilder();
        sb.append("<table>\n<tr><th>Time</th><th>Level</th><th>Message</th><th>Source</th></tr>\n");
        for (LogEntry entry : entries) {
            sb.append("<tr>");
            sb.append("<td>").append(encodeForHtmlContent(entry.timestamp)).append("</td>");
            sb.append("<td>").append(encodeForHtmlContent(entry.level)).append("</td>");
            sb.append("<td>").append(encodeForHtmlContent(entry.message)).append("</td>");
            sb.append("<td>").append(encodeForHtmlContent(entry.source)).append("</td>");
            sb.append("</tr>\n");
        }
        sb.append("</table>\n");
        return sb.toString();
    }

    /**
     * Builds client-side navigation script for paginating through entries.
     * Uses entry metadata to build filter controls.
     */
    static String buildNavigationScript(TenantContext ctx, List<LogEntry> entries) {
        Set<String> sources = new LinkedHashSet<>();
        for (LogEntry entry : entries) {
            sources.add(entry.source);
        }
        StringBuilder sb = new StringBuilder();
        sb.append("<script>\n");
        sb.append("(function() {\n");
        sb.append("  var tenant = \"").append(encodeForJsString(ctx.tenantId)).append("\";\n");
        sb.append("  var sources = [");
        boolean first = true;
        for (String source : sources) {
            if (!first) sb.append(",");
            sb.append("\"").append(encodeForJsString(source)).append("\"");
            first = false;
        }
        sb.append("];\n");
        sb.append("  var filterDiv = document.createElement('div');\n");
        sb.append("  filterDiv.className = 'filters';\n");
        sb.append("  sources.forEach(function(src) {\n");
        sb.append("    var btn = document.createElement('button');\n");
        sb.append("    btn.textContent = src;\n");
        sb.append("    btn.onclick = function() { filterBySource(src); };\n");
        sb.append("    filterDiv.appendChild(btn);\n");
        sb.append("  });\n");
        sb.append("  document.querySelector('.container').prepend(filterDiv);\n");
        sb.append("})();\n");
        sb.append("</script>\n");
        return sb.toString();
    }

    /**
     * Encodes a string for safe inclusion in HTML content context.
     */
    static String encodeForHtmlContent(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;");
    }

    /**
     * Encodes a string for safe inclusion inside a JavaScript string literal.
     * Handles standard escape sequences for JS string context.
     */
    static String encodeForJsString(String input) {
        if (input == null) return "";
        StringBuilder sb = new StringBuilder();
        for (char c : input.toCharArray()) {
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '"': sb.append("\\\""); break;
                case '\'': sb.append("\\'"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '<': sb.append("\\u003c"); break;
                case '>': sb.append("\\u003e"); break;
                case '/': sb.append("\\/"); break;
                default: sb.append(c);
            }
        }
        return sb.toString();
    }

    static void writeReport(TenantContext ctx, String reportType, String html) throws IOException {
        Path outDir = BASE_DIR.resolve(ctx.tenantId).resolve("reports");
        Files.createDirectories(outDir);
        Path outFile = outDir.resolve(reportType.replaceAll("[^a-zA-Z0-9_-]", "_") + ".html");
        if (!outFile.toRealPath().startsWith(BASE_DIR.toRealPath())) {
            throw new SecurityException("Path traversal detected");
        }
        Files.writeString(outFile, html);
    }

    static class TenantContext {
        final String tenantId;
        final String theme;
        TenantContext(String tenantId, String theme) {
            this.tenantId = tenantId;
            this.theme = theme;
        }
    }

    static class LogEntry {
        final String timestamp;
        final String level;
        final String message;
        final String source;

        LogEntry(String timestamp, String level, String message, String source) {
            this.timestamp = timestamp;
            this.level = level;
            this.message = message;
            this.source = source;
        }

        static LogEntry parse(String line) {
            // Format: timestamp|level|source|message
            String[] parts = line.split("\\|", 4);
            if (parts.length == 4) {
                return new LogEntry(parts[0], parts[1], parts[3], parts[2]);
            }
            return new LogEntry("unknown", "INFO", line, "unknown");
        }
    }
}
